import * as THREE from 'three';
import {createClimbingModel} from './climbing-model.js';
import {createClimbingSession,fitClimbingCamera} from './climbing-session.js';
export const CLIMBING_BODY=`<div class="gym-layout"><div class="gym-court" id="climbing-court" role="img" aria-label="원래 도름이가 낮은 손잡이와 발 디딤돌을 하나씩 옮기는 모습" tabindex="0"></div><section class="gym-panel climbing-panel" id="climbing-panel"><p id="climbing-status" role="status"></p><div class="gym-actions"><button id="climbing-start">연습 시작</button><button id="climbing-pause">잠깐 쉬기</button><button id="climbing-exit">내려와서 나오기</button></div><div class="gym-hold" id="climbing-manual-controls"><button id="climbing-choice-0">다음 손잡이</button><button id="climbing-choice-1">다른 길</button></div><div class="gym-hold" id="climbing-hold-controls"><button id="climbing-hold">누르는 동안 한 칸씩</button></div><p id="climbing-score" role="status"></p><details id="climbing-options"><summary>연습 설정</summary><label>연습 방법 <select id="climbing-mode"><option value="manual" selected>손잡이 직접 고르기</option><option value="easy">편하게 · 쉬운 길 따라가기</option><option value="hold">누르는 동안 쉬운 길 따라가기</option></select></label></details><details id="climbing-help"><summary>안내 보기</summary><p>혼자 낮은 벽을 연습해요. 처음 왼손은 초록색의 편한 길과 노란색의 조금 높은 길 중 골라요. 이후에는 닿을 수 있는 손잡이와 발 디딤돌만 보여요.</p><p>1 · 2 또는 ← · →로 고르고, 길게 누르기는 스페이스를 써요. 한 번에 손이나 발 하나만 옮기며 나머지 세 곳을 딛어요. 도름이의 손발이 실제로 닿고 몸이 안정되면 한 칸으로 세요.</p><p>여섯 칸을 마치면 쉬어요. 나가기는 왔던 길을 되짚어 두 발을 매트에 내리고 나와요. 안내를 접어도 자세는 유지돼요. 보상이나 저장되는 기록은 없어요. NPC 대결은 아직 준비 중이에요.</p></details></section></div>`;
export function createClimbingController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},doc=globalThis.document,win=globalThis.window,sessionFactory=createClimbingSession,modelFactory=createClimbingModel,fitCamera=fitClimbingCamera}){
 const camera=new THREE.OrthographicCamera(),$=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 function listen(node,type,fn,opts){if(!node)return;node.addEventListener(type,fn,opts);live.listeners.push([node,type,fn,opts]);}
 function clear(){clearInput();if(!live)return;live.pointers.clear();live.keys.clear();live.model.setInput({held:false});}
 function held(){if(live)live.model.setInput({held:live.pointers.size>0||live.keys.size>0});}
 function render(){if(!live)return;const s=live.model.snapshot(),p=live.session.phase,paused=live.suspended||s.paused,ready=live.session.ready&&['idle','ready','stopped'].includes(s.state);$('climbing-status').textContent=paused?'멈췄어요. 계속하기를 누르면 이어져요':p==='boarding'?'매트를 지나 낮은 디딤돌에 올라가요':p==='guarding'?'두 발을 딛고 손잡이를 잡아요':p==='lowering'||p==='exiting'?'손을 내리고 두 발을 매트로 내려요':live.exiting?'세 곳을 딛고 왔던 길로 돌아와요':s.state==='complete'?'여섯 칸을 마쳤어요. 여기서 쉬거나 내려와요':ready?'준비됐어요. 시작은 직접 골라요':s.blocked?'손발이 닿는 자리를 확인하고 있어요':s.moving?'세 곳을 딛고 하나씩 옮겨요':'다음 닿을 곳을 골라요';$('climbing-score').textContent=`안정되게 옮긴 곳 ${s.completed} / 6`;$('climbing-start').disabled=!ready||paused||live.exiting;$('climbing-pause').textContent=paused?'계속하기':'잠깐 쉬기';$('climbing-exit').disabled=live.exiting;$('climbing-mode').disabled=!ready||paused||live.exiting;for(let i=0;i<2;i++){const b=$('climbing-choice-'+i),c=s.choices[i];b.textContent=c?.label??'다음 자리를 준비해요';b.disabled=!c||s.mode!=='manual'||paused||live.exiting;b.hidden=i===1&&!c;}$('climbing-hold').disabled=s.mode!=='hold'||s.state!=='active'||paused||live.exiting;$('climbing-manual-controls').hidden=s.mode!=='manual';$('climbing-hold-controls').hidden=s.mode!=='hold';}
 function clean({restore}={}){pending=false;generation++;if(!live)return;const old=live;live=null;old.observer?.disconnect();for(const[n,t,f,o]of old.listeners)n.removeEventListener(t,f,o);old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){const owned=!!live||pending;clean();if(owned)ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.suspended=false;live.model.resume();live.exiting=true;live.model.stop('exit');live.session.requestExit();render();}
 function pause(){if(!live)return;clear();live.suspended=true;live.model.pause();live.session.pause?.();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView();if(!source?.schoolView?.gymView?.climbing)return false;pending=true;const token=++generation;
 const accepted=ui.workshop('클라이밍 · 낮은 벽 혼자 연습',CLIMBING_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});live={session,model:modelFactory({mode:'manual'}),source,listeners:[],pointers:new Set(),keys:new Set(),suspended:false,exiting:false,fit:''};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
  const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
  act('climbing-start',()=>{clear();if(live.session.ready)live.model.start();render();});act('climbing-exit',close);act('climbing-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
  for(const id of['climbing-mode'])listen($(id),'input',()=>{clear();live.model.setMode($(id).value);render();});
  for(let i=0;i<2;i++)act('climbing-choice-'+i,()=>{const choice=live.model.snapshot().choices[i];if(choice)live.model.choose(choice.id);render();});
  const button=$('climbing-hold');listen(button,'pointerdown',e=>{if(button.disabled||e.button!==0||e.isPrimary===false)return;e.preventDefault();live.cancelledPointer=false;button.setPointerCapture?.(e.pointerId);live.pointers.add(e.pointerId);held();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(button,type,e=>{if(!live)return;if(type!=='pointerup')live.cancelledPointer=true;live.pointers.delete(e.pointerId);held();});
  listen(doc,'keydown',e=>{if(!live||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const control=e.target?.closest?.('button,a,summary,[role="button"]')??(['BUTTON','A','SUMMARY'].includes(e.target?.tagName)?e.target:null);if(control&&control!==button)return;const s=live.model.snapshot();if(live.suspended||s.paused||live.exiting||s.state!=='active')return;if(e.code==='Space'&&s.mode==='hold'){e.preventDefault();live.keys.add(e.code);held();}else if(s.mode==='manual'&&['ArrowLeft','ArrowRight','Digit1','Digit2'].includes(e.code)){e.preventDefault();const choice=s.choices[['ArrowRight','Digit2'].includes(e.code)?1:0];if(choice)live.model.choose(choice.id);render();}});listen(doc,'keyup',e=>{if(live){live.keys.delete(e.code);held();}});
  listen($('climbing-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('climbing-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
  const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
  listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live&&token===generation)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('climbing-court'));}render();resize();$('climbing-court').focus();return()=>{if(token===generation)clean();};
 }catch(error){if(live)clean();else session?.dispose();pending=false;ui.close();ui.toast('클라이밍 매트 앞에 빈자리가 필요해요. 잠깐 뒤 다시 해 주세요');}},{kind:'gym-workshop climbing-workshop',closeLabel:'내려와서 나오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('클라이밍 연습을 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}try{const s=live.model.snapshot();if(!live.suspended&&!s.paused){if(live.session.ready&&s.state==='idle')live.model.ready();live.session.tick(dt,live.model);if(live.session.ready&&live.model.snapshot().state==='idle')live.model.ready();}if(live.session.done){clean();ui.close();return;}render();viewport(stage.clientWidth,stage.clientHeight);}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('climbing-court').getBoundingClientRect(),a=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-a.left),y:Math.max(0,b.top-a.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},key=Object.values(rect).join(',')+live.session.phase;if(key!==live.fit){try{fitCamera(camera,live.session.root,rect,live.session.snapshot());live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,pause,tick,viewport,camera,dispose:cancel,get active(){return!!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,session:live.session.snapshot(),exiting:live.exiting}:null};
}
